340	export function injectInteractiveVisualBaseStyles(html: string) {
341	  if (/data-primoria-visual-base/i.test(html)) {
342	    return html;
343	  }
344	
345	  const styleTag = `<style data-primoria-visual-base>\n${PRIMORIA_INTERACTIVE_VISUAL_BASE_CSS}\n</style>`;
346	  if (/<head[^>]*>/i.test(html)) {
347	    return html.replace(/<head[^>]*>/i, (headTag) => `${headTag}\n${styleTag}`);
348	  }
349	
350	  if (/<html[^>]*>/i.test(html)) {
351	    return html.replace(/<html[^>]*>/i, (htmlTag) => `${htmlTag}\n<head>\n${styleTag}\n</head>`);
352	  }
