357	export function validateOfflineHtml(html: string) {
358	  if (!isCompleteHtmlDocument(html)) {
359	    throw new Error('Interactive visuals must be complete HTML documents.');
360	  }
361	  if (/<script[^>]+src\s*=/i.test(html)) {
362	    throw new Error('Interactive visuals must use inline JavaScript only.');
363	  }
364	  if (/<script[^>]+type\s*=\s*["']?module/i.test(html)) {
365	    throw new Error('Interactive visuals must not use module scripts.');
366	  }
367	  if (/<link[^>]+href\s*=/i.test(html)) {
368	    throw new Error('Interactive visuals must not load external stylesheets.');
369	  }
370	  if (/<(iframe|embed|object)\b/i.test(html)) {
371	    throw new Error('Interactive visuals cannot embed external frames.');
372	  }
373	  if (/\bhttps?:\/\//i.test(removeAllowedNamespaceUrls(html))) {
374	    throw new Error('Interactive visuals must be fully offline and cannot reference external URLs.');
