499	function stripHtmlMarkdownFence(text: string) {
500	  const trimmed = text.trim();
501	  const fenced = /^```(?:html)?\s*([\s\S]*?)\s*```$/i.exec(trimmed)?.[1];
502	  return (fenced ?? trimmed).trim();
503	}
504	
505	export function extractInteractiveVisualHtml(text: string) {
506	  const stripped = stripHtmlMarkdownFence(text);
507	  const startMatch = /<!doctype html[\s>]|<html[\s>]/i.exec(stripped);
508	  if (!startMatch) {
509	    return null;
510	  }
511	
512	  const fromStart = stripped.slice(startMatch.index).trim();
513	  const endIndex = fromStart.toLowerCase().lastIndexOf('</html>');
514	  if (endIndex === -1) {
515	    return fromStart;
516	  }
517	
518	  return fromStart.slice(0, endIndex + '</html>'.length).trim();
519	}
