532	    /<meta[^>]+content\s*=\s*(["'])(.*?)\1[^>]+name\s*=\s*(["'])description\3/i.exec(html)?.[2];
533	  if (metaDescription?.trim()) {
534	    return metaDescription.trim();
535	  }
536	
537	  const subtitle = /class\s*=\s*(["'])[^"']*\biv-subtitle\b[^"']*\1[^>]*>([\s\S]*?)<\/[^>]+>/i.exec(html)?.[2];
538	  return subtitle ? stripTags(subtitle) : undefined;
539	}
