541	function summarizePrompt(prompt: string, language: 'en' | 'zh-CN' | undefined) {
542	  const normalized = prompt.replace(/\s+/g, ' ').trim();
543	  if (!normalized) {
544	    return language === 'zh-CN' ? '交互式可视化' : 'Interactive Visual';
545	  }
546	  return normalized.length > 42 ? `${normalized.slice(0, 39).trim()}...` : normalized;
