556	  if (/(一次函数|线性函数|linear function|y\s*=\s*a\s*x\s*\+\s*b|y\s*=\s*ax\s*\+\s*b|slope|intercept|斜率|截距)/i.test(topicText)) {
557	    return 'linear-function-graph';
558	  }
559	  if (/(sin|sine|cos|cosine|trig|三角函数|正弦|余弦)/i.test(topicText)) {
560	    return 'trigonometry-graph';
561	  }
562	  if (/(wave|amplitude|frequency|phase|波|振幅|频率)/i.test(topicText)) {
563	    return 'wave';
564	  }
565	  return 'generic';
566	}
