568	function inferGeneratedExperienceMode(payload: z.infer<typeof RequestSchema>) {
569	  if (payload.experienceMode) {
570	    return payload.experienceMode;
571	  }
572	
573	  const topicText = payload.prompt.toLowerCase();
574	  if (/(graph|plot|chart|curve|function|函数|图像|图表|曲线|坐标)/i.test(topicText)) {
575	    return 'graph' as const;
576	  }
577	  if (/(scenario|case|situation|情境|场景)/i.test(topicText)) {
578	    return 'scenario' as const;
579	  }
580	  if (/(story|narrative|故事)/i.test(topicText)) {
