593	  return {
594	    title: payload.title?.trim() || extractHtmlTitle(generatedHtml) || summarizePrompt(payload.prompt, payload.language),
595	    description:
596	      payload.description?.trim() ||
597	      extractHtmlDescription(generatedHtml) ||
598	      (payload.language === 'zh-CN'
599	        ? '操作控件，观察关键概念如何随参数实时变化。'
600	        : 'Use the controls to see how the core concept changes in real time.'),
601	    template: inferGeneratedTemplate(payload),
602	    experienceMode: inferGeneratedExperienceMode(payload),
603	    themeTone: 'primoria-system',
604	    generatedHtml,
605	  };
606	}
607	
608	class GenerationAttemptError extends Error {
609	  kind: 'transient' | 'validation' | 'fatal';
610	  httpStatus?: number;
611	
612	  constructor(message: string, kind: 'transient' | 'validation' | 'fatal', httpStatus?: number) {
613	    super(message);
614	    this.name = 'GenerationAttemptError';
615	    this.kind = kind;
616	    this.httpStatus = httpStatus;
617	  }
618	}
619	
620	function isGenerationAttemptError(error: unknown): error is GenerationAttemptError {
621	  return error instanceof GenerationAttemptError;
622	}
623	
624	function isTransientGeminiStatus(status: number) {
625	  return status === 429 || status === 500 || status === 502 || status === 503 || status === 504;
626	}
627	
628	function sleep(ms: number) {
629	  return new Promise((resolve) => setTimeout(resolve, ms));
630	}
631	
632	function buildRepairInstruction(errors: string[]) {
633	  if (!errors.length) {
634	    return '';
635	  }
636	
637	  return `
638	Previous generated HTML failed validation. Fix the HTML and return the complete document again.
639	Validation errors to fix:
640	${errors.map((error, index) => `${index + 1}. ${error}`).join('\n')}
641	Preserve the same educational intent. Do not explain the fix.
642	`.trim();
643	}
644	
645	async function generateInteractiveVisual(payload: z.infer<typeof RequestSchema>, repairErrors: string[] = []) {
646	  const geminiApiKey = getEnv('GEMINI_API_KEY');
647	  let lastError = 'AI interactive visual generation failed.';
648	  let lastKind: 'transient' | 'validation' | 'fatal' = 'fatal';
649	  let lastHttpStatus: number | undefined;
650	  const prompt = [buildInteractiveVisualPrompt(payload), buildRepairInstruction(repairErrors)].filter(Boolean).join('\n\n');
651	
652	  for (const model of [DEFAULT_MODEL, ...FALLBACK_MODELS.filter((candidate) => candidate !== DEFAULT_MODEL)]) {
653	    const response = await fetch(`${GEMINI_BASE_URL}/models/${model}:generateContent?key=${geminiApiKey}`, {
654	      method: 'POST',
655	      headers: { 'Content-Type': 'application/json' },
656	      body: JSON.stringify({
657	        system_instruction: {
658	          parts: [{
659	            text: 'You create safe, offline, interactive educational HTML documents for sandboxed iframes. Return only one complete runnable HTML document. Do not return JSON or markdown.',
660	          }],
661	        },
662	        contents: [{ role: 'user', parts: [{ text: prompt }] }],
663	        generationConfig: {
664	          temperature: 0.45,
665	          maxOutputTokens: MAX_OUTPUT_TOKENS,
666	        },
667	      }),
668	    });
669	
670	    if (!response.ok) {
671	      lastError = `Gemini returned HTTP ${response.status}.`;
672	      lastKind = isTransientGeminiStatus(response.status) ? 'transient' : 'fatal';
673	      lastHttpStatus = response.status;
674	      continue;
675	    }
676	
677	    lastHttpStatus = undefined;
678	    const raw = (await response.json()) as Record<string, unknown>;
679	    const candidateTexts = extractGeminiCandidateTexts(raw);
680	    if (!candidateTexts.length) {
681	      lastError = 'Gemini returned an empty response.';
682	      lastKind = 'transient';
683	      continue;
684	    }
685	
686	    for (const text of candidateTexts) {
687	      const html = extractInteractiveVisualHtml(text);
688	      if (!html) {
689	        lastError = 'Gemini did not return a complete HTML document.';
690	        lastKind = 'validation';
691	        continue;
692	      }
693	
694	      try {
695	        validateOfflineHtml(html);
696	        return buildInteractiveVisualArtifactFromHtml(payload, html);
697	      } catch (error) {
698	        lastError = error instanceof Error ? error.message : 'Interactive visual HTML validation failed.';
699	        lastKind = 'validation';
700	        continue;
701	      }
702	    }
703	  }
704	
705	  throw new GenerationAttemptError(lastError, lastKind, lastHttpStatus);
706	}
707	
708	function normalizeErrorHistory(value: unknown) {
709	  return Array.isArray(value) ? (value as JobErrorEntry[]) : [];
710	}
711	
712	export function serializeJob(row: JobRow) {
713	  return {
714	    id: row.id,
715	    status: row.status,
716	    prompt: row.prompt,
717	    requestPayload: row.request_payload,
718	    resultArtifact: row.result_artifact,
719	    lastError: row.last_error,
720	    errorHistory: normalizeErrorHistory(row.error_history),
721	    attemptCount: row.attempt_count,
722	    nextAttemptAt: row.next_attempt_at,
723	    createdAt: row.created_at,
724	    updatedAt: row.updated_at,
725	    completedAt: row.completed_at,
726	  };
727	}
728	
729	function artifactResponse(generated: ReturnType<typeof buildInteractiveVisualArtifactFromHtml>, prompt: string) {
730	  return {
731	    version: '1',
732	    engine: 'gemini-html5',
733	    title: generated.title,
734	    description: generated.description,
735	    template: generated.template,
736	    experienceMode: generated.experienceMode,
737	    themeTone: generated.themeTone,
738	    aiPrompt: prompt,
739	    generatedHtml: generated.generatedHtml,
740	  };
741	}
742	
743	function appendErrorHistory(
744	  history: JobErrorEntry[],
745	  entry: JobErrorEntry,
746	) {
747	  return [...history, entry].slice(-30);
748	}
749	
750	function countErrorKind(history: JobErrorEntry[], kind: JobErrorEntry['kind']) {
751	  return history.filter((entry) => entry.kind === kind).length;
752	}
753	
754	function nextTransientRetryDelay(history: JobErrorEntry[]) {
755	  const transientCount = countErrorKind(history, 'transient');
756	  return TRANSIENT_RETRY_DELAYS_MS[Math.min(Math.max(transientCount - 1, 0), TRANSIENT_RETRY_DELAYS_MS.length - 1)];
757	}
