759	async function fetchJob(serviceClient: ReturnType<typeof createServiceClient>, jobId: string) {
760	  const { data, error } = await serviceClient
761	    .from(JOB_TABLE)
762	    .select('*')
763	    .eq('id', jobId)
764	    .maybeSingle();
765	
766	  if (error) {
767	    throw error;
768	  }
769	  return data as JobRow | null;
770	}
771	
772	async function fetchUserJob(serviceClient: ReturnType<typeof createServiceClient>, jobId: string, userId: string) {
773	  const job = await fetchJob(serviceClient, jobId);
774	  if (!job || job.user_id !== userId) {
775	    return null;
776	  }
777	  return job;
778	}
779	
780	async function createGenerationJob(
781	  serviceClient: ReturnType<typeof createServiceClient>,
782	  userId: string,
783	  payload: InteractiveVisualPayload,
784	) {
785	  const { data, error } = await serviceClient
786	    .from(JOB_TABLE)
787	    .insert({
788	      user_id: userId,
789	      status: 'queued',
790	      prompt: payload.prompt,
791	      request_payload: payload,
792	      error_history: [],
793	      attempt_count: 0,
794	    })
795	    .select('*')
796	    .single();
797	
798	  if (error) {
799	    throw error;
800	  }
801	  return data as JobRow;
802	}
803	
804	async function markJob(
805	  serviceClient: ReturnType<typeof createServiceClient>,
806	  jobId: string,
807	  patch: Record<string, unknown>,
808	) {
809	  const { data, error } = await serviceClient
810	    .from(JOB_TABLE)
811	    .update(patch)
812	    .eq('id', jobId)
813	    .select('*')
814	    .single();
815	
816	  if (error) {
817	    throw error;
818	  }
819	  return data as JobRow;
820	}
821	
822	async function fetchDueJobs(serviceClient: ReturnType<typeof createServiceClient>, limit: number) {
823	  const nowIso = new Date().toISOString();
824	  const staleIso = new Date(Date.now() - STALE_RUNNING_AFTER_MS).toISOString();
825	  const [{ data: queued, error: queuedError }, { data: stale, error: staleError }] = await Promise.all([
826	    serviceClient
827	      .from(JOB_TABLE)
828	      .select('*')
829	      .eq('status', 'queued')
830	      .order('created_at', { ascending: true })
831	      .limit(limit * 5),
832	    serviceClient
833	      .from(JOB_TABLE)
834	      .select('*')
835	      .eq('status', 'running')
836	      .lt('updated_at', staleIso)
837	      .order('updated_at', { ascending: true })
838	      .limit(limit),
839	  ]);
840	
841	  if (queuedError) {
842	    throw queuedError;
843	  }
844	  if (staleError) {
845	    throw staleError;
846	  }
847	
848	  const byId = new Map<string, JobRow>();
849	  for (const row of [
850	    ...((queued ?? []) as JobRow[]).filter((candidate) => !candidate.next_attempt_at || candidate.next_attempt_at <= nowIso),
851	    ...((stale ?? []) as JobRow[]),
852	  ]) {
853	    byId.set(row.id, row);
854	  }
855	  return Array.from(byId.values()).slice(0, limit);
856	}
857	
858	async function processSingleJob(
859	  serviceClient: ReturnType<typeof createServiceClient>,
860	  initialJob: JobRow,
861	  options: { followRetries: boolean },
862	) {
863	  let job = initialJob;
864	
865	  while (job.status !== 'succeeded' && job.status !== 'failed') {
866	    const payload = RequestSchema.parse(job.request_payload);
867	    const history = normalizeErrorHistory(job.error_history);
868	    const validationErrors = history
869	      .filter((entry) => entry.kind === 'validation')
870	      .map((entry) => entry.message)
871	      .slice(-MAX_VALIDATION_REPAIRS);
872	    const attempt = job.attempt_count + 1;
873	
874	    job = await markJob(serviceClient, job.id, {
875	      status: 'running',
876	      attempt_count: attempt,
877	      next_attempt_at: null,
878	      completed_at: null,
879	    });
880	
881	    try {
882	      const generated = await generateInteractiveVisual(payload, validationErrors);
883	      const responseArtifact = artifactResponse(generated, payload.prompt);
884	      job = await markJob(serviceClient, job.id, {
885	        status: 'succeeded',
886	        result_artifact: responseArtifact,
887	        last_error: null,
888	        next_attempt_at: null,
889	        completed_at: new Date().toISOString(),
890	      });
891	      return job;
892	    } catch (error) {
893	      const generationError = isGenerationAttemptError(error)
894	        ? error
895	        : new GenerationAttemptError(error instanceof Error ? error.message : 'Interactive visual generation failed.', 'fatal');
896	      const retryable =
897	        (generationError.kind === 'validation' && countErrorKind(history, 'validation') < MAX_VALIDATION_REPAIRS) ||
898	        (generationError.kind === 'transient' && countErrorKind(history, 'transient') < MAX_TRANSIENT_RETRIES);
899	      const nextAttemptAt =
900	        generationError.kind === 'transient' && retryable
901	          ? new Date(Date.now() + nextTransientRetryDelay([...history, {
902	              at: new Date().toISOString(),
903	              attempt,
904	              kind: generationError.kind,
905	              message: generationError.message,
906	              retryable,
907	              httpStatus: generationError.httpStatus,
908	            }])).toISOString()
909	          : undefined;
910	      const entry: JobErrorEntry = {
911	        at: new Date().toISOString(),
912	        attempt,
913	        kind: generationError.kind,
914	        message: generationError.message,
915	        retryable,
916	        nextAttemptAt,
917	        httpStatus: generationError.httpStatus,
918	      };
919	      const nextHistory = appendErrorHistory(history, entry);
920	
921	      if (!retryable) {
922	        job = await markJob(serviceClient, job.id, {
923	          status: 'failed',
924	          last_error: generationError.message,
925	          error_history: nextHistory,
926	          next_attempt_at: null,
927	          completed_at: new Date().toISOString(),
928	        });
929	        return job;
930	      }
931	
932	      job = await markJob(serviceClient, job.id, {
933	        status: generationError.kind === 'transient' ? 'queued' : 'running',
934	        last_error: generationError.message,
935	        error_history: nextHistory,
936	        next_attempt_at: nextAttemptAt ?? null,
937	      });
938	
939	      if (generationError.kind === 'validation') {
940	        continue;
941	      }
942	
943	      if (!options.followRetries) {
944	        return job;
945	      }
946	
947	      await sleep(Math.max(0, Date.parse(nextAttemptAt ?? new Date().toISOString()) - Date.now()));
948	      const refreshed = await fetchJob(serviceClient, job.id);
949	      if (!refreshed || refreshed.status === 'succeeded' || refreshed.status === 'failed') {
950	        return refreshed ?? job;
951	      }
952	      job = refreshed;
953	    }
954	  }
955	
956	  return job;
957	}
958	
959	async function processGenerationJobs({
960	  jobId,
961	  userId,
962	  followRetries,
963	}: {
964	  jobId?: string;
965	  userId?: string;
966	  followRetries: boolean;
967	}) {
968	  const serviceClient = createServiceClient();
969	  const jobs = jobId
970	    ? [userId ? await fetchUserJob(serviceClient, jobId, userId) : await fetchJob(serviceClient, jobId)].filter(Boolean) as JobRow[]
971	    : await fetchDueJobs(serviceClient, QUEUE_PROCESS_LIMIT);
972	
973	  const processed: Array<ReturnType<typeof serializeJob>> = [];
974	  for (const job of jobs) {
975	    const latest = await processSingleJob(serviceClient, job, { followRetries });
976	    if (latest) {
977	      processed.push(serializeJob(latest));
978	    }
979	  }
980	
981	  return {
982	    processed: processed.length,
983	    jobs: processed,
984	  };
985	}
986	
987	function scheduleJobProcessing(jobId: string) {
988	  const promise = processGenerationJobs({ jobId, followRetries: true }).catch((error) => {
989	    console.error('[viewer-ai-interactive-visual] background processing failed', error);
990	  });
991	  const maybeRuntime = (globalThis as unknown as { EdgeRuntime?: { waitUntil?: (promise: Promise<unknown>) => void } }).EdgeRuntime;
992	  if (typeof maybeRuntime?.waitUntil === 'function') {
993	    maybeRuntime.waitUntil(promise);
994	    return;
995	  }
996	  void promise;
997	}
998	
999	export async function handler(req: Request) {
1000	  if (req.method === 'OPTIONS') {
1001	    return new Response('ok', { headers: corsHeaders });
1002	  }
1003	
1004	  try {
1005	    if (req.method === 'GET') {
1006	      const user = await getAuthenticatedUser(req);
1007	      if (!user) {
1008	        return jsonResponse({ error: 'Unauthorized' }, 401);
1009	      }
1010	      const jobId = new URL(req.url).searchParams.get('jobId') ?? '';
1011	      if (!jobId) {
1012	        return jsonResponse({ error: 'jobId is required.' }, 400);
1013	      }
1014	      const job = await fetchUserJob(createServiceClient(), jobId, user.id);
1015	      if (!job) {
1016	        return jsonResponse({ error: 'Generation job was not found.' }, 404);
1017	      }
1018	      return jsonResponse({ job: serializeJob(job) });
1019	    }
1020	
1021	    const body = await req.json().catch(() => ({}));
1022	    const action = ActionSchema.parse(body).action ?? 'sync';
1023	
1024	    if (action === 'process') {
1025	      const actionPayload = ActionSchema.parse(body);
1026	      if (isQueueWorkerRequest(req)) {
1027	        const summary = await processGenerationJobs({ jobId: actionPayload.jobId, followRetries: false });
1028	        return jsonResponse(summary);
1029	      }
1030	
1031	      const user = await getAuthenticatedUser(req);
1032	      if (!user || !actionPayload.jobId) {
1033	        return jsonResponse({ error: 'Unauthorized' }, 401);
1034	      }
1035	      const summary = await processGenerationJobs({
1036	        jobId: actionPayload.jobId,
1037	        userId: user.id,
1038	        followRetries: true,
1039	      });
1040	      return jsonResponse(summary);
1041	    }
1042	
1043	    const user = await getAuthenticatedUser(req);
1044	    if (!user) {
1045	      return jsonResponse({ error: 'Unauthorized' }, 401);
1046	    }
1047	
1048	    if (action === 'status') {
1049	      const jobId = ActionSchema.parse(body).jobId;
1050	      if (!jobId) {
1051	        return jsonResponse({ error: 'jobId is required.' }, 400);
1052	      }
1053	      const job = await fetchUserJob(createServiceClient(), jobId, user.id);
1054	      if (!job) {
1055	        return jsonResponse({ error: 'Generation job was not found.' }, 404);
1056	      }
1057	      return jsonResponse({ job: serializeJob(job) });
1058	    }
1059	
1060	    if (action === 'create') {
1061	      const payload = RequestSchema.parse(body);
1062	      const job = await createGenerationJob(createServiceClient(), user.id, payload);
1063	      scheduleJobProcessing(job.id);
1064	      return jsonResponse({ jobId: job.id, status: job.status, job: serializeJob(job) }, 202);
1065	    }
1066	
1067	    const payload = RequestSchema.parse(body);
1068	    const generated = await generateInteractiveVisual(payload);
1069	    return jsonResponse(artifactResponse(generated, payload.prompt));
1070	  } catch (error) {
1071	    return jsonResponse(
1072	      {
1073	        error: error instanceof Error ? error.message : 'Interactive visual generation failed.',
1074	      },
1075	      400,
1076	    );
1077	  }
1078	}
1079	
1080	if (import.meta.main) {
1081	  serve(handler);
1082	}
