1	import {
2	  inferInteractiveVisualMode,
3	  type InteractiveVisualMode,
4	} from '@/shared/interactive/interactiveVisualModes';
5	
6	export type InteractiveVisualArtifact = {
7	  version: string;
8	  engine: string;
9	  template: string;
10	  experienceMode: InteractiveVisualMode;
11	  title: string;
12	  description?: string;
13	  aiPrompt?: string;
14	  generatedHtml: string;
15	  themeTone?: string;
16	  runtime?: Record<string, unknown>;
17	};
18	
19	type InteractiveVisualGenerationRequest = {
20	  prompt: string;
21	  template?: string;
22	  experienceMode?: InteractiveVisualMode;
23	  language?: 'en' | 'zh-CN';
24	};
25	
26	const DEFAULT_HEIGHT = 430;
27	const MAX_HEIGHT = 900;
28	const MIN_HEIGHT = 320;
29	const EMBED_EVENT_TYPE = 'primoria:interactive-visual-height';
30	const ANALYTICS_EVENT_TYPE = 'primoria:interactive-visual-analytics';
31	
32	function trimOptionalString(value: unknown) {
33	  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
34	}
35	
36	function stripMarkdownFences(value: string) {
37	  const trimmed = value.trim();
38	  const fenced = /```(?:html)?\s*([\s\S]*?)```/i.exec(trimmed)?.[1];
39	  return (fenced ?? trimmed).trim();
40	}
41	
42	function humanizePrompt(prompt: string) {
43	  return prompt
44	    .replace(/\s+/g, ' ')
45	    .trim()
46	    .replace(/^[a-z]/, (value) => value.toUpperCase());
47	}
48	
49	function summarizePrompt(prompt: string, fallback: string) {
50	  const normalized = humanizePrompt(prompt);
51	  if (!normalized) {
52	    return fallback;
53	  }
54	  return normalized.length > 72 ? `${normalized.slice(0, 69).trim()}...` : normalized;
55	}
56	
57	export function inferInteractiveVisualTemplate(prompt: string, preferredTemplate?: string) {
58	  const normalizedPrompt = prompt.toLowerCase();
59	  const normalizedTemplate = preferredTemplate?.trim().toLowerCase();
60	
61	  if (normalizedTemplate && normalizedTemplate !== 'generic') {
62	    return normalizedTemplate;
63	  }
64	
65	  if (/(cos|cosine|sine|sin|wave|curve|trig|frequency|amplitude|phase)/i.test(normalizedPrompt)) {
66	    return 'wave';
67	  }
68	  if (/(pendulum|swing|oscillat)/i.test(normalizedPrompt)) {
69	    return 'pendulum';
70	  }
71	  if (/(projectile|trajectory|parabola|launch angle|launch)/i.test(normalizedPrompt)) {
72	    return 'projectile';
73	  }
74	  if (/(newton|force|collision|momentum|action|reaction)/i.test(normalizedPrompt)) {
75	    return 'collision';
76	  }
77	  return 'generic';
78	}
79	
80	export function shouldGenerateInteractiveVisualForPrompt(prompt: string) {
81	  const normalized = prompt.toLowerCase();
82	  return /(interactive|animate|animated|visual|visualise|visualize|simulation|simulator|graph|curve|wave|cosine|sine|trig|pendulum|projectile|collision|force|newton|orbit|diagram)/i.test(
83	    normalized,
84	  );
85	}
86	
87	function removeAllowedNamespaceUrls(html: string) {
88	  return html
89	    .replace(
90	      /\sxmlns(?::[A-Za-z][\w.-]*)?\s*=\s*(["'])https?:\/\/www\.w3\.org\/(?:2000\/svg|1999\/xlink)\1/gi,
91	      '',
92	    )
93	    .replace(
94	      /(["'])https?:\/\/www\.w3\.org\/(?:2000\/svg|1999\/xlink)\1/gi,
95	      '$1$1',
96	    );
97	}
98	
99	export function validateOfflineInteractiveHtml(html: string) {
100	  const normalized = stripMarkdownFences(html);
101	  if (!normalized) {
102	    return 'Interactive visual HTML is empty.';
103	  }
104	
105	  if (/<script[^>]+src\s*=/i.test(normalized)) {
106	    return 'Interactive visuals must use inline JavaScript only.';
107	  }
108	  if (/<script[^>]+type\s*=\s*["']?module/i.test(normalized)) {
109	    return 'Interactive visuals must not use module scripts.';
110	  }
111	  if (/<link[^>]+href\s*=/i.test(normalized)) {
112	    return 'Interactive visuals must not load external stylesheets.';
113	  }
114	  if (/<(iframe|object|embed)\b/i.test(normalized)) {
115	    return 'Interactive visuals cannot embed external frames or objects.';
116	  }
117	  if (/\bhttps?:\/\//i.test(removeAllowedNamespaceUrls(normalized))) {
118	    return 'Interactive visuals must run offline and cannot reference external URLs.';
119	  }
120	  if (/\bfetch\s*\(/i.test(normalized) || /\bXMLHttpRequest\b/i.test(normalized) || /\bWebSocket\b/i.test(normalized) || /\bimport\s*\(/i.test(normalized)) {
121	    return 'Interactive visuals must run offline and cannot request network resources.';
122	  }
123	
124	  return null;
125	}
126	
127	export function normalizeInteractiveVisualArtifact(
128	  value: unknown,
129	  options: { prompt?: string; template?: string; experienceMode?: InteractiveVisualMode } = {},
130	): InteractiveVisualArtifact | null {
131	  if (!value || typeof value !== 'object') {
132	    return null;
133	  }
134	
135	  const record = value as Record<string, unknown>;
136	  const generatedHtml = trimOptionalString(record.generatedHtml ?? record.html ?? record.generated_html);
137	  if (!generatedHtml) {
138	    return null;
139	  }
140	
141	  const offlineError = validateOfflineInteractiveHtml(generatedHtml);
142	  if (offlineError) {
143	    throw new Error(offlineError);
144	  }
145	
146	  const prompt = trimOptionalString(record.aiPrompt) ?? options.prompt;
147	  const template = trimOptionalString(record.template) ?? inferInteractiveVisualTemplate(prompt ?? '', options.template);
148	  const experienceMode = inferInteractiveVisualMode(
149	    prompt ?? '',
150	    trimOptionalString(record.experienceMode ?? record.experience_mode) ?? options.experienceMode ?? null,
151	  );
152	
153	  return {
154	    version: trimOptionalString(record.version) ?? '1',
155	    engine: trimOptionalString(record.engine) ?? 'interactive-html5',
156	    template,
157	    experienceMode,
158	    title:
159	      trimOptionalString(record.title) ??
160	      summarizePrompt(prompt ?? '', template === 'generic' ? 'AI Element' : `${template[0]?.toUpperCase() ?? ''}${template.slice(1)} Explorer`),
161	    description: trimOptionalString(record.description),
162	    aiPrompt: prompt,
163	    generatedHtml: stripMarkdownFences(generatedHtml),
164	    themeTone: trimOptionalString(record.themeTone ?? record.theme_tone),
165	    runtime: record.runtime && typeof record.runtime === 'object' ? (record.runtime as Record<string, unknown>) : undefined,
166	  };
