188	      :root {
189	        color-scheme: light;
190	      }
191	      html, body {
192	        margin: 0;
193	        padding: 0;
194	        background: transparent;
195	        overflow-x: hidden;
196	        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
197	      }
198	      body {
199	        min-height: 100vh;
200	      }
201	      *, *::before, *::after {
202	        box-sizing: border-box;
203	      }
204	    </style>
205	  </head>
206	  <body>
207	    ${fragment}
208	    <script>
209	      (function () {
210	        const EVENT_TYPE = '${EMBED_EVENT_TYPE}';
211	        const ANALYTICS_TYPE = '${ANALYTICS_EVENT_TYPE}';
212	        function track(eventName, payload) {
213	          parent.postMessage(
214	            {
215	              type: ANALYTICS_TYPE,
216	              eventName: eventName,
217	              payload: payload && typeof payload === 'object' ? payload : {}
218	            },
219	            '*'
220	          );
221	        }
222	
223	        window.PrimoriaInteractive = {
224	          track: track,
225	        };
226	
227	        function measure() {
228	          const height = Math.max(
229	            document.documentElement.scrollHeight,
230	            document.body.scrollHeight,
231	            document.documentElement.offsetHeight,
232	            document.body.offsetHeight
233	          );
234	          parent.postMessage({ type: EVENT_TYPE, height: height }, '*');
235	        }
236	
237	        const resizeObserver = new ResizeObserver(measure);
238	        resizeObserver.observe(document.body);
239	        document.addEventListener('click', function (event) {
240	          const target = event.target instanceof Element ? event.target.closest('button,[role="button"],[data-primoria-action]') : null;
241	          if (!target) {
242	            return;
243	          }
244	          track('action_clicked', {
245	            controlId: target.getAttribute('id') || target.getAttribute('data-primoria-action') || target.textContent?.trim()?.slice(0, 80) || 'action',
246	            tagName: target.tagName.toLowerCase(),
247	          });
248	        });
249	        document.addEventListener('input', function (event) {
250	          const target = event.target;
251	          if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement)) {
252	            return;
253	          }
254	          track('control_changed', {
255	            controlId: target.id || target.name || target.getAttribute('aria-label') || target.tagName.toLowerCase(),
256	            inputType: target instanceof HTMLInputElement ? target.type || 'text' : target.tagName.toLowerCase(),
257	            value:
258	              target instanceof HTMLInputElement && (target.type === 'checkbox' || target.type === 'radio')
259	                ? Boolean(target.checked)
260	                : String(target.value).slice(0, 120),
261	          });
262	        });
263	        window.addEventListener('load', measure);
264	        window.addEventListener('load', function () {
265	          track('visual_loaded', { title: ${JSON.stringify(title || 'Interactive visual')} });
266	        });
267	        window.addEventListener('resize', measure);
268	        requestAnimationFrame(measure);
269	        setTimeout(measure, 120);
270	        setTimeout(measure, 600);
271	      })();
272	    </script>
