567	      let animationOffset = 0;
568	      let lastTime = performance.now();
569	      let isAnimating = true;
570	
571	      function readState() {
572	        return {
573	          amplitude: Number(controls.amplitude.value),
574	          frequency: Number(controls.frequency.value),
575	          phase: Number(controls.phase.value),
576	          shift: Number(controls.shift.value),
