578	        };
579	      }
580	
581	      function format(value) {
582	        return Number(value).toFixed(2);
583	      }
584	
585	      function syncOutputs() {
586	        const state = readState();
587	        Object.keys(outputs).forEach((key) => {
588	          outputs[key].textContent = format(state[key]);
589	        });
590	        statOutputs.amplitude.textContent = format(state.amplitude);
591	        statOutputs.frequency.textContent = format(state.frequency);
592	        statOutputs.phase.textContent = format(state.phase);
593	        statOutputs.shift.textContent = format(state.shift);
594	      }
595	
596	      function draw(timestamp) {
597	        const state = readState();
598	        const elapsed = (timestamp - lastTime) / 1000;
599	        lastTime = timestamp;
600	        if (isAnimating) {
601	          animationOffset += elapsed * state.speed;
602	        }
603	
604	        context.clearRect(0, 0, canvas.width, canvas.height);
605	        context.fillStyle = '#f7fbff';
606	        context.fillRect(0, 0, canvas.width, canvas.height);
607	
608	        const padding = { left: 72, right: 36, top: 30, bottom: 54 };
609	        const plotWidth = canvas.width - padding.left - padding.right;
610	        const plotHeight = canvas.height - padding.top - padding.bottom;
611	        const centerY = padding.top + plotHeight / 2 - state.shift * (plotHeight / 6);
612	        const amplitudePx = state.amplitude * (plotHeight / 5.2);
613	
614	        context.strokeStyle = 'rgba(79, 133, 181, 0.16)';
615	        context.lineWidth = 1;
616	        for (let grid = 0; grid <= 8; grid += 1) {
617	          const x = padding.left + (plotWidth / 8) * grid;
618	          context.beginPath();
619	          context.moveTo(x, padding.top);
620	          context.lineTo(x, padding.top + plotHeight);
621	          context.stroke();
622	        }
623	        for (let grid = 0; grid <= 6; grid += 1) {
624	          const y = padding.top + (plotHeight / 6) * grid;
625	          context.beginPath();
626	          context.moveTo(padding.left, y);
627	          context.lineTo(padding.left + plotWidth, y);
628	          context.stroke();
629	        }
630	
631	        context.strokeStyle = '#295d93';
632	        context.lineWidth = 2;
633	        context.beginPath();
634	        context.moveTo(padding.left, centerY);
635	        context.lineTo(padding.left + plotWidth, centerY);
636	        context.stroke();
637	
638	        context.beginPath();
639	        context.moveTo(padding.left, padding.top);
640	        context.lineTo(padding.left, padding.top + plotHeight);
641	        context.stroke();
642	
643	        context.fillStyle = '#51779f';
644	        context.font = '600 16px Inter, sans-serif';
645	        context.fillText('${labels.xAxis}', canvas.width - 88, centerY - 10);
646	        context.fillText('${labels.yAxis}', padding.left + 10, padding.top + 20);
647	
648	        context.beginPath();
649	        for (let pixel = 0; pixel <= plotWidth; pixel += 1) {
650	          const t = pixel / plotWidth;
651	          const radians = t * Math.PI * 2 * 2 * state.frequency + state.phase + animationOffset;
652	          const y = centerY - Math.cos(radians) * amplitudePx;
653	          const x = padding.left + pixel;
654	          if (pixel === 0) {
655	            context.moveTo(x, y);
656	          } else {
657	            context.lineTo(x, y);
658	          }
659	        }
660	        context.strokeStyle = '#35a0f6';
661	        context.lineWidth = 4;
662	        context.stroke();
663	
664	        const highlightX = padding.left + plotWidth * 0.72;
665	        const highlightRadians =
666	          ((highlightX - padding.left) / plotWidth) * Math.PI * 4 * state.frequency + state.phase + animationOffset;
667	        const highlightY = centerY - Math.cos(highlightRadians) * amplitudePx;
668	
669	        context.fillStyle = '#2684d2';
670	        context.beginPath();
671	        context.arc(highlightX, highlightY, 8, 0, Math.PI * 2);
672	        context.fill();
673	
674	        context.fillStyle = 'rgba(38, 132, 210, 0.16)';
675	        context.beginPath();
676	        context.arc(highlightX, highlightY, 18, 0, Math.PI * 2);
677	        context.fill();
678	
679	        requestAnimationFrame(draw);
680	      }
681	
682	      Object.values(controls).forEach((input) => {
683	        input.addEventListener('input', syncOutputs);
684	      });
685	
686	      toggleButton.addEventListener('click', () => {
687	        isAnimating = !isAnimating;
688	        toggleButton.textContent = isAnimating ? '${labels.pause}' : '${labels.play}';
689	      });
690	
