697	        animationOffset = 0;
698	        isAnimating = true;
699	        toggleButton.textContent = '${labels.pause}';
700	        syncOutputs();
701	      });
702	
703	      syncOutputs();
704	      requestAnimationFrame((timestamp) => {
705	        lastTime = timestamp;
706	        draw(timestamp);
707	      });
708	    </script>
709	  `;
