774	      const gravityInput = document.getElementById('gravity');
775	      const dampingInput = document.getElementById('damping');
776	      const angleValue = document.getElementById('angleValue');
777	      const lengthValue = document.getElementById('lengthValue');
778	      const gravityValue = document.getElementById('gravityValue');
779	      const dampingValue = document.getElementById('dampingValue');
780	      const toggleButton = document.getElementById('togglePendulum');
781	      const resetButton = document.getElementById('resetPendulum');
782	      let isRunning = true;
783	      let theta = 25 * Math.PI / 180;
784	      let omega = 0;
785	      let lastTime = performance.now();
786	
787	      function syncLabels() {
788	        angleValue.textContent = Number(angleInput.value).toFixed(0) + '°';
789	        lengthValue.textContent = Number(lengthInput.value).toFixed(2) + ' m';
790	        gravityValue.textContent = Number(gravityInput.value).toFixed(2) + ' m/s²';
791	        dampingValue.textContent = Number(dampingInput.value).toFixed(3);
792	      }
793	
794	      function resetState() {
795	        theta = Number(angleInput.value) * Math.PI / 180;
796	        omega = 0;
797	      }
798	
799	      function draw(timestamp) {
800	        const dt = Math.min((timestamp - lastTime) / 1000, 0.032);
801	        lastTime = timestamp;
802	        const lengthMeters = Number(lengthInput.value);
803	        const gravity = Number(gravityInput.value);
804	        const damping = Number(dampingInput.value);
805	
806	        if (isRunning) {
807	          const alpha = -(gravity / lengthMeters) * Math.sin(theta) - damping * omega;
808	          omega += alpha * dt;
809	          theta += omega * dt;
810	        }
811	
812	        ctx.clearRect(0, 0, canvas.width, canvas.height);
813	        ctx.fillStyle = '#fff9f1';
814	        ctx.fillRect(0, 0, canvas.width, canvas.height);
815	
816	        const anchorX = canvas.width / 2;
817	        const anchorY = 72;
818	        const armLength = 120 + lengthMeters * 120;
819	        const bobX = anchorX + Math.sin(theta) * armLength;
820	        const bobY = anchorY + Math.cos(theta) * armLength;
821	
822	        ctx.strokeStyle = '#b99159';
823	        ctx.lineWidth = 4;
824	        ctx.beginPath();
825	        ctx.moveTo(anchorX, anchorY);
826	        ctx.lineTo(bobX, bobY);
827	        ctx.stroke();
828	
829	        ctx.fillStyle = '#d4b07b';
830	        ctx.beginPath();
831	        ctx.arc(anchorX, anchorY, 11, 0, Math.PI * 2);
832	        ctx.fill();
833	
834	        ctx.fillStyle = '#c68b3d';
835	        ctx.beginPath();
836	        ctx.arc(bobX, bobY, 28, 0, Math.PI * 2);
837	        ctx.fill();
838	
839	        ctx.strokeStyle = 'rgba(198, 139, 61, 0.22)';
840	        ctx.lineWidth = 1;
841	        ctx.beginPath();
842	        ctx.arc(anchorX, anchorY, armLength, Math.PI / 2 - 1.2, Math.PI / 2 + 1.2);
843	        ctx.stroke();
844	
845	        requestAnimationFrame(draw);
846	      }
847	
848	      [angleInput, lengthInput, gravityInput, dampingInput].forEach((input) => {
849	        input.addEventListener('input', () => {
850	          syncLabels();
851	          if (input === angleInput || input === lengthInput) {
852	            resetState();
853	          }
854	        });
855	      });
856	
857	      toggleButton.addEventListener('click', () => {
858	        isRunning = !isRunning;
859	      });
860	      resetButton.addEventListener('click', () => {
861	        angleInput.value = '25';
862	        lengthInput.value = '1.4';
863	        gravityInput.value = '9.81';
864	        dampingInput.value = '0.01';
865	        syncLabels();
866	        resetState();
867	        isRunning = true;
868	      });
869	
870	      syncLabels();
871	      resetState();
872	      requestAnimationFrame((timestamp) => {
873	        lastTime = timestamp;
874	        draw(timestamp);
875	      });
876	    </script>
877	  `;
878	}
