1	import { supabase, viewerSupabaseAnonKey, viewerSupabaseUrl } from '@/shared/api/supabase';
2	import { usesViewerFixtures } from '@/shared/api/viewer/core';
3	import {
4	  createInteractiveVisualFallback,
5	  normalizeInteractiveVisualArtifact,
6	  type InteractiveVisualArtifact,
7	} from '@/shared/interactive/interactiveVisual';
8	import type { InteractiveVisualMode } from '@/shared/interactive/interactiveVisualModes';
9	
10	export type InteractiveVisualGenerationJobStatus = 'queued' | 'running' | 'succeeded' | 'failed';
11	
12	export type InteractiveVisualGenerationErrorEntry = {
13	  at: string;
14	  attempt: number;
15	  kind: 'transient' | 'validation' | 'fatal';
16	  message: string;
17	  retryable: boolean;
18	  nextAttemptAt?: string;
19	  httpStatus?: number;
20	};
21	
22	export type InteractiveVisualGenerationJob = {
23	  id: string;
24	  status: InteractiveVisualGenerationJobStatus;
25	  prompt: string;
26	  requestPayload: Record<string, unknown>;
27	  resultArtifact?: unknown;
28	  lastError?: string;
29	  errorHistory: InteractiveVisualGenerationErrorEntry[];
30	  attemptCount: number;
31	  nextAttemptAt?: string;
32	  createdAt?: string;
33	  updatedAt?: string;
34	  completedAt?: string;
35	};
36	
37	export type CreateInteractiveVisualRequest = {
38	  prompt: string;
39	  template?: string;
40	  experienceMode?: InteractiveVisualMode;
41	  title?: string;
42	  description?: string;
43	  language?: 'en' | 'zh-CN';
44	  surface?: 'builder' | 'ai-tutor';
45	  allowFallback?: boolean;
46	  onJobUpdate?: (job: InteractiveVisualGenerationJob) => void;
47	  timeoutMs?: number;
48	};
49	
50	const DEFAULT_JOB_TIMEOUT_MS = 180_000;
51	const DEFAULT_JOB_POLL_MS = 1_500;
52	
53	async function getInteractiveVisualAccessToken() {
54	  const { data, error } = await supabase.auth.getSession();
55	  if (error) {
56	    throw error;
57	  }
58	  return data.session?.access_token ?? null;
59	}
60	
61	function buildInteractiveVisualFunctionUrl() {
62	  if (!viewerSupabaseUrl || viewerSupabaseUrl.includes('placeholder')) {
63	    throw new Error('Interactive visual generation requires Supabase configuration.');
64	  }
65	  if (!viewerSupabaseAnonKey || viewerSupabaseAnonKey === 'placeholder') {
66	    throw new Error('Interactive visual generation requires Supabase configuration.');
67	  }
68	
69	  if (viewerSupabaseUrl.includes('.supabase.co')) {
70	    return `${viewerSupabaseUrl.replace('.supabase.co', '.functions.supabase.co')}/viewer-ai-interactive-visual`;
71	  }
72	
73	  return `${viewerSupabaseUrl.replace(/\/$/, '')}/functions/v1/viewer-ai-interactive-visual`;
74	}
75	
76	function parseErrorPayload(raw: string): { message?: unknown; error?: unknown; code?: unknown } | null {
77	  try {
78	    const parsed = JSON.parse(raw) as unknown;
79	    return parsed && typeof parsed === 'object' ? (parsed as { message?: unknown; error?: unknown; code?: unknown }) : null;
80	  } catch {
81	    return null;
82	  }
83	}
84	
85	function errorTextFromPayload(payload: { message?: unknown; error?: unknown; code?: unknown } | null, fallback: string) {
86	  if (typeof payload?.message === 'string' && payload.message.trim()) {
87	    return payload.message;
88	  }
89	  if (typeof payload?.error === 'string' && payload.error.trim()) {
90	    return payload.error;
91	  }
92	  if (typeof payload?.code === 'string' && payload.code.trim()) {
93	    return payload.code;
94	  }
95	  return fallback;
96	}
97	
98	async function buildInteractiveVisualError(response: Response) {
99	  const raw = await response.text();
100	  const payload = parseErrorPayload(raw);
101	  const normalizedText = `${response.status} ${raw} ${errorTextFromPayload(payload, '')}`.toLowerCase();
102	
103	  if (response.status === 404 && (normalizedText.includes('not_found') || normalizedText.includes('not found'))) {
104	    return new Error('Interactive visual generation function is not deployed.');
105	  }
106	
107	  if (response.status === 401 || response.status === 403) {
108	    return new Error('Please sign in before generating an interactive visual.');
109	  }
110	
111	  if (response.status >= 500) {
112	    return new Error('Interactive visual generation service is temporarily unavailable.');
113	  }
114	
115	  return new Error(errorTextFromPayload(payload, raw || 'AI interactive visual generation failed.'));
116	}
117	
118	function normalizeErrorHistory(value: unknown): InteractiveVisualGenerationErrorEntry[] {
119	  return Array.isArray(value)
120	    ? value.filter((entry): entry is InteractiveVisualGenerationErrorEntry => Boolean(entry && typeof entry === 'object'))
121	    : [];
122	}
123	
124	function normalizeGenerationJob(value: unknown): InteractiveVisualGenerationJob | null {
125	  if (!value || typeof value !== 'object') {
126	    return null;
127	  }
128	  const record = value as Record<string, unknown>;
129	  const id = typeof record.id === 'string' ? record.id : '';
130	  const status = typeof record.status === 'string' ? record.status : '';
131	  if (!id || !['queued', 'running', 'succeeded', 'failed'].includes(status)) {
132	    return null;
133	  }
134	
135	  return {
136	    id,
137	    status: status as InteractiveVisualGenerationJobStatus,
138	    prompt: typeof record.prompt === 'string' ? record.prompt : '',
139	    requestPayload: record.requestPayload && typeof record.requestPayload === 'object'
140	      ? (record.requestPayload as Record<string, unknown>)
141	      : {},
142	    resultArtifact: record.resultArtifact,
143	    lastError: typeof record.lastError === 'string' ? record.lastError : undefined,
144	    errorHistory: normalizeErrorHistory(record.errorHistory),
145	    attemptCount: typeof record.attemptCount === 'number' ? record.attemptCount : 0,
146	    nextAttemptAt: typeof record.nextAttemptAt === 'string' ? record.nextAttemptAt : undefined,
147	    createdAt: typeof record.createdAt === 'string' ? record.createdAt : undefined,
148	    updatedAt: typeof record.updatedAt === 'string' ? record.updatedAt : undefined,
149	    completedAt: typeof record.completedAt === 'string' ? record.completedAt : undefined,
150	  };
151	}
152	
153	async function fetchInteractiveVisualFunction(body: Record<string, unknown>, accessToken: string) {
154	  const response = await fetch(buildInteractiveVisualFunctionUrl(), {
155	    method: 'POST',
156	    headers: {
157	      'Content-Type': 'application/json',
158	      apikey: viewerSupabaseAnonKey,
159	      Authorization: `Bearer ${accessToken}`,
160	    },
161	    body: JSON.stringify(body),
162	  });
163	
164	  if (!response.ok) {
165	    throw await buildInteractiveVisualError(response);
166	  }
167	
168	  return (await response.json()) as unknown;
169	}
170	
171	export async function createInteractiveVisualJob(
172	  request: CreateInteractiveVisualRequest,
173	): Promise<InteractiveVisualGenerationJob> {
174	  const accessToken = await getInteractiveVisualAccessToken();
175	  if (!accessToken) {
176	    throw new Error('Please sign in before generating an interactive visual.');
177	  }
178	
179	  const data = await fetchInteractiveVisualFunction(
180	    {
181	      action: 'create',
182	      prompt: request.prompt.trim(),
183	      template: request.template,
184	      experienceMode: request.experienceMode,
185	      title: request.title,
186	      description: request.description,
187	      language: request.language ?? 'en',
188	      surface: request.surface ?? 'builder',
189	    },
190	    accessToken,
191	  );
192	  const job = normalizeGenerationJob((data as { job?: unknown }).job);
193	  if (!job) {
194	    throw new Error('Interactive visual generation did not return a job.');
195	  }
196	  return job;
197	}
198	
199	export async function getInteractiveVisualJob(jobId: string): Promise<InteractiveVisualGenerationJob> {
200	  const accessToken = await getInteractiveVisualAccessToken();
201	  if (!accessToken) {
202	    throw new Error('Please sign in before generating an interactive visual.');
203	  }
204	
205	  const data = await fetchInteractiveVisualFunction({ action: 'status', jobId }, accessToken);
206	  const job = normalizeGenerationJob((data as { job?: unknown }).job);
207	  if (!job) {
208	    throw new Error('Interactive visual generation job was not found.');
209	  }
210	  return job;
211	}
212	
213	function nextPollDelay(job: InteractiveVisualGenerationJob) {
214	  if (!job.nextAttemptAt) {
215	    return DEFAULT_JOB_POLL_MS;
216	  }
217	  const waitForNextAttempt = Date.parse(job.nextAttemptAt) - Date.now();
218	  if (!Number.isFinite(waitForNextAttempt) || waitForNextAttempt <= 0) {
219	    return DEFAULT_JOB_POLL_MS;
220	  }
221	  return Math.min(Math.max(waitForNextAttempt, DEFAULT_JOB_POLL_MS), 5_000);
222	}
223	
224	function delay(ms: number) {
225	  return new Promise((resolve) => setTimeout(resolve, ms));
226	}
227	
228	async function waitForInteractiveVisualJob(
229	  job: InteractiveVisualGenerationJob,
230	  request: CreateInteractiveVisualRequest,
231	): Promise<InteractiveVisualArtifact> {
232	  const startedAt = Date.now();
233	  let current = job;
234	  request.onJobUpdate?.(current);
235	
236	  while (Date.now() - startedAt < (request.timeoutMs ?? DEFAULT_JOB_TIMEOUT_MS)) {
237	    if (current.status === 'succeeded') {
238	      const artifact = normalizeInteractiveVisualArtifact(current.resultArtifact, {
239	        prompt: request.prompt,
240	        template: request.template,
241	        experienceMode: request.experienceMode,
242	      });
243	      if (!artifact) {
244	        throw new Error('AI interactive visual generation returned an empty result.');
245	      }
246	      return artifact;
247	    }
248	
249	    if (current.status === 'failed') {
250	      throw new Error(current.lastError ?? 'AI interactive visual generation failed.');
251	    }
252	
253	    await delay(nextPollDelay(current));
254	    current = await getInteractiveVisualJob(current.id);
255	    request.onJobUpdate?.(current);
256	  }
257	
258	  throw new Error('Interactive visual generation timed out. Please check the generation job later.');
259	}
260	
261	export async function createInteractiveVisual(
262	  request: CreateInteractiveVisualRequest,
263	): Promise<InteractiveVisualArtifact> {
264	  const prompt = request.prompt.trim();
265	  if (!prompt) {
266	    throw new Error('An AI element prompt is required.');
267	  }
268	
269	  if (usesViewerFixtures()) {
270	    return createInteractiveVisualFallback(request);
271	  }
272	
273	  try {
274	    const job = await createInteractiveVisualJob({ ...request, prompt });
275	    return await waitForInteractiveVisualJob(job, { ...request, prompt });
276	  } catch (error) {
277	    if (request.allowFallback === false) {
278	      throw error;
279	    }
280	    return createInteractiveVisualFallback(request);
281	  }
282	}
283

