import path from 'path';
import { writeFile } from 'node:fs/promises';
import react from '@vitejs/plugin-react';
import { defineConfig, loadEnv, type Plugin } from 'vite';

function interactiveVisualDebugLogPlugin(): Plugin {
  const logPath = path.resolve(__dirname, '../../.iv-debug.json');
  return {
    name: 'iv-debug-log',
    apply: 'serve',
    configureServer(server) {
      server.middlewares.use('/__dev/iv-log', (req, res) => {
        if (req.method !== 'POST') {
          res.statusCode = 405;
          res.end('POST only');
          return;
        }
        const chunks: Buffer[] = [];
        req.on('data', (chunk: Buffer) => chunks.push(chunk));
        req.on('end', () => {
          const body = Buffer.concat(chunks).toString('utf8');
          let pretty = body;
          try {
            pretty = JSON.stringify(JSON.parse(body), null, 2);
          } catch {
            // keep raw body if it isn't JSON
          }
          writeFile(logPath, pretty, 'utf8')
            .then(() => {
              res.statusCode = 204;
              res.end();
            })
            .catch((error) => {
              res.statusCode = 500;
              res.end(`failed to write log: ${(error as Error).message}`);
            });
        });
      });
    },
  };
}

