  interactions: z
    .array(
      z.object({
        control: z.string().min(2),
        purpose: z.string().min(2),
      }),
    )
    .min(1)
    .max(8),
  accessibilityNotes: z.array(z.string().min(2)).min(1).max(6),
  observationCopyHint: z.string().min(2).max(280),
