export type Plan = z.infer<typeof PlanSchema>;

function stripJsonFence(text: string) {
  const trimmed = text.trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(trimmed)?.[1];
  return (fenced ?? trimmed).trim();
}

function extractFirstJsonObject(text: string): string | null {
  const stripped = stripJsonFence(text);
  const start = stripped.indexOf('{');
  if (start === -1) {
    return null;
  }

  let depth = 0;
  let inString = false;
  let stringChar = '';
  let escape = false;
  for (let i = start; i < stripped.length; i += 1) {
    const ch = stripped[i];
    if (escape) {
      escape = false;
      continue;
    }
    if (ch === '\\' && inString) {
      escape = true;
      continue;
    }
    if (inString) {
      if (ch === stringChar) {
        inString = false;
      }
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = true;
      stringChar = ch;
      continue;
    }
    if (ch === '{') {
      depth += 1;
    } else if (ch === '}') {
      depth -= 1;
      if (depth === 0) {
        return stripped.slice(start, i + 1);
      }
    }
  }
  return null;
}

export class PlanParseError extends Error {
  issues: string[];
  raw: string;
  constructor(message: string, issues: string[], raw: string) {
    super(message);
    this.name = 'PlanParseError';
    this.issues = issues;
    this.raw = raw;
  }
}

export function parsePlanText(raw: string): Plan {
  const jsonText = extractFirstJsonObject(raw);
  if (!jsonText) {
    throw new PlanParseError(
      'Plan response did not contain a JSON object.',
      ['No "{...}" object found in response.'],
      raw,
    );
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonText);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'unknown JSON error';
    throw new PlanParseError(
      'Plan response was not valid JSON.',
      [message],
      raw,
    );
  }

  const result = PlanSchema.safeParse(parsed);
  if (!result.success) {
    const issues = result.error.issues.map((issue) => `${issue.path.join('.') || '(root)'}: ${issue.message}`);
    throw new PlanParseError('Plan JSON did not match the required schema.', issues, raw);
  }
  return result.data;
}

