<body>

<div class="iv-shell">
  <header class="iv-header">
    <p class="iv-kicker">核心概念</p>
    <h1 class="iv-title">变量、值与内存地址</h1>
    <p class="iv-subtitle">变量名如何指向内存中的特定位置来存储和更新数据？通过逐步执行代码来一探究竟。</p>
  </header>

  <main class="iv-layout">
    <div class="iv-visual-card">
      <div class="code-container">
        <div class="code-line-highlighter"></div>
        <pre><code class="code-block" aria-live="polite" aria-label="示例代码"><span class="code-line">let fruit = "apple";</span><span class="code-line">let quantity = 5;</span><span class="code-line">let price = 10;</span><span class="code-line">fruit = "orange";</span></code></pre>
      </div>
      <svg class="visualization-svg" viewBox="0 0 400 350"></svg>
    </div>

    <div class="iv-controls-card">
      <div class="iv-section-title">代码执行控制</div>
      <div class="iv-control-row">
        <button id="next-step-btn" class="iv-button iv-button-primary" aria-label="执行下一行代码">下一步</button>
        <button id="reset-btn" class="iv-button iv-button-secondary" aria-label="重置模拟">重置</button>
      </div>
      <div class="iv-observation-card">
        <p id="observation-text" class="iv-conclusion" aria-live="polite">
          点击“下一步”开始执行代码，观察变量和内存的变化。
        </p>
      </div>
    </div>
  </main>
</div>

<script type="module">
  import * as d3 from "https://esm.sh/d3";
  import gsap from "https://esm.sh/gsap";

  // --- DATA & STATE ---
  const codeLines = document.querySelectorAll('.code-line');
  const codeLineHeight = codeLines[0].offsetHeight;
  const highlighter = document.querySelector('.code-line-highlighter');
  gsap.set(highlighter, { height: codeLineHeight });

  const steps = [
    { // Step 0: Initial state
      line: -1,
      action: 'init',
      observation: "点击“下一步”开始执行代码，观察变量和内存的变化。"
    },
    { // Step 1: let fruit = "apple";
      line: 0,
      action: 'declare',
      variable: 'fruit',
      value: '"apple"',
      memoryAddress: '0x01',
      observation: "执行第1行：声明变量 `fruit` 并赋值 `\"apple\"`，数据存储在内存地址 0x01。"
    },
    { // Step 2: let quantity = 5;
      line: 1,
      action: 'declare',
      variable: 'quantity',
      value: 5,
      memoryAddress: '0x02',
      observation: "执行第2行：声明变量 `quantity` 并赋值 `5`，数据存储在内存地址 0x02。"
    },
    { // Step 3: let price = 10;
      line: 2,
      action: 'declare',
      variable: 'price',
      value: 10,
      memoryAddress: '0x03',
      observation: "执行第3行：声明变量 `price` 并赋值 `10`，数据存储在内存地址 0x03。"
    },
    { // Step 4: fruit = "orange";
      line: 3,
      action: 'reassign',
      variable: 'fruit',
      value: '"orange"',
      memoryAddress: '0x01',
      observation: "执行第4行：变量 `fruit` 被重新赋值为 `\"orange\"`，内存地址 0x01 中的旧值被覆盖。"
    }
  ];

  let currentStep = 0;
  const state = {
    variables: new Map(), // { name: { labelEl, pointerEl, memoryAddress } }
  };

  // --- DOM ELEMENTS ---
  const nextBtn = document.getElementById('next-step-btn');
  const resetBtn = document.getElementById('reset-btn');
  const observationText = document.getElementById('observation-text');
  const svg = d3.select(".visualization-svg");
  const width = 400;
  const height = 350;

  // --- SVG SETUP ---
  const memoryCellData = [
    { address: '0x01', x: 250, y: 50 },
    { address: '0x02', x: 250, y: 120 },
    { address: '0x03', x: 250, y: 190 },
    { address: '0x04', x: 250, y: 260 },
  ];

  const variablePositions = {
    'fruit': { x: 50, y: 85 },
    'quantity': { x: 50, y: 155 },
    'price': { x: 50, y: 225 },
  };

  // Define arrowhead marker
  svg.append('defs').append('marker')
    .attr('id', 'arrowhead')
    .attr('viewBox', '-0 -5 10 10')
    .attr('refX', 8)
    .attr('refY', 0)
    .attr('orient', 'auto')
    .attr('markerWidth', 8)
    .attr('markerHeight', 8)
    .attr('xoverflow', 'visible')
    .append('svg:path')
    .attr('d', 'M 0,-5 L 10 ,0 L 0,5')
    .attr('fill', 'var(--color-accent-primary)')
    .style('stroke', 'none');

  const gVariables = svg.append('g').attr('class', 'variables-group');
  const gPointers = svg.append('g').attr('class', 'pointers-group');
  const gMemory = svg.append('g').attr('class', 'memory-group');

  // Draw memory cells
  const memoryCells = gMemory.selectAll('g.memory-cell')
    .data(memoryCellData)
    .join('g')
    .attr('class', 'memory-cell')
    .attr('id', d => `mem-${d.address.replace('0x', '')}`)
    .attr('transform', d => `translate(${d.x}, ${d.y})`);

  memoryCells.append('rect')
    .attr('width', 120)
    .attr('height', 50)
    .attr('rx', var(--radius-sm));

  memoryCells.append('text')
    .attr('class', 'address-label')
    .attr('x', 115)
    .attr('y', -5)
    .attr('text-anchor', 'end')
    .text(d => d.address);

  memoryCells.append('text')
    .attr('class', 'value-label')
    .attr('x', 60)
    .attr('y', 29)
    .attr('text-anchor', 'middle')
    .text('');

  // --- FUNCTIONS ---
  function updateUI() {
    const stepData = steps[currentStep];

    // Update highlighter
    if (stepData.line >= 0) {
      const yOffset = codeLines[stepData.line].offsetTop;
      gsap.to(highlighter, {
        y: yOffset,
        duration: var(--duration-slow),
        ease: var(--ease-standard)
      });
    } else {
       gsap.to(highlighter, { y: -100, duration: var(--duration-slow), ease: var(--ease-standard) });
    }

    // Update observation text
    observationText.innerHTML = stepData.observation;

    // Handle actions
    if (stepData.action === 'declare') {
      declareVariable(stepData);
    } else if (stepData.action === 'reassign') {
      reassignVariable(stepData);
    } else if (stepData.action === 'init') {
      resetVisualization();
    }

    // Update button states
    nextBtn.disabled = currentStep >= steps.length - 1;
    resetBtn.disabled = currentStep === 0;
  }

  function declareVariable({ variable, value, memoryAddress }) {
    const pos = variablePositions[variable];
    const memCell = d3.select(`#mem-${memoryAddress.replace('0x','')}`);
    const memPos = {
        x: parseFloat(memCell.attr('transform').split('(')[1]) + 10,
        y: parseFloat(memCell.attr('transform').split(',')[1].replace(')','')) + 25
    };

    // 1. Create variable label
    const label = gVariables.append('text')
      .attr('class', 'variable-label')
      .attr('x', pos.x)
      .attr('y', pos.y)
      .attr('text-anchor', 'middle')
      .text(variable)
      .attr('opacity', 0);

    gsap.to(label.node(), { opacity: 1, duration: var(--duration-base) });

    // 2. Create pointer
    const path = gPointers.append('path')
      .attr('class', 'pointer')
      .attr('d', `M ${pos.x + 30},${pos.y - 5} L ${memPos.x},${memPos.y}`);

    const pathLength = path.node().getTotalLength();
    gsap.from(path.node(), {
      strokeDasharray: pathLength,
      strokeDashoffset: pathLength,
      duration: var(--duration-slow),
      ease: 'power2.inOut',
      delay: 0.1
    });

    // 3. Update memory value
    const valueText = memCell.select('.value-label');
    valueText.text(value).attr('class', `value-label ${typeof value === 'string' ? 'string-value' : ''}`);
    gsap.from(valueText.node(), {
      y: '+=15',
      opacity: 0,
      duration: var(--duration-base),
      ease: 'back.out(1.7)',
      delay: 0.3
    });

    state.variables.set(variable, { labelEl: label, pointerEl: path, memoryAddress });
  }

  function reassignVariable({ variable, value, memoryAddress }) {
    const varData = state.variables.get(variable);
    const memCell = d3.select(`#mem-${memoryAddress.replace('0x','')}`);
    const valueText = memCell.select('.value-label');

    // 1. Flash pointer
    gsap.to(varData.pointerEl.node(), {
      stroke: 'var(--color-accent-secondary)',
      repeat: 1,
      yoyo: true,
      duration: var(--duration-base) / 2,
      ease: 'power1.inOut'
    });

    // 2. Update value with fade out/in
    const tl = gsap.timeline({ delay: 0.1 });
    tl.to(valueText.node(), {
      opacity: 0,
