                    <div class="iv-control-label-group">
                        <label for="animationSpeedSlider" class="iv-label">动画速度</label>
                        <span id="animationSpeedValue" class="iv-value">中</span>
                    </div>
                    <input type="range" id="animationSpeedSlider" min="0.1" max="1.0" step="0.05" value="0.22" aria-label="调整排序动画的播放速度">
                </div>
            </div>
