    <script type="module">
        import gsap from "https://esm.sh/gsap";

        // --- Primoria Interactive Tracking Bridge ---
        // Ensure window.PrimoriaInteractive is available
        if (typeof window.PrimoriaInteractive === 'undefined') {
            window.PrimoriaInteractive = {
                track: (eventName, payload) => {
                    console.log(`[PrimoriaInteractive.track] Event: ${eventName}, Payload:`, payload);
                }
            };
        }

        // --- Configuration and DOM Elements ---
        const ARRAY_SIZE = 10;
        const INITIAL_MIN_VALUE = 10;
        const INITIAL_MAX_VALUE = 99;
        const SVG_WIDTH = 600;
        const SVG_HEIGHT = 300;
        const BAR_SPACING_RATIO = 0.1; // Ratio of spacing to bar width

        const svg = document.getElementById('bubbleSortSVG');
        const nextStepButton = document.getElementById('nextStepButton');
        const resetButton = document.getElementById('resetButton');
        const speedSlider = document.getElementById('animationSpeedSlider');
        const animationSpeedValue = document.getElementById('animationSpeedValue');
        const observationText = document.getElementById('observationText');

        let arr = [];
        let i = 0; // Outer loop index (passes)
        let j = 0; // Inner loop index (comparisons in current pass)
        let sortedCount = 0; // Number of elements confirmed in their final sorted position
        let isSortingComplete = false;
        let animationDuration = parseFloat(speedSlider.value); // Initial animation duration

        // --- CSS Token Values (read at runtime) ---
        let accentPrimaryColor;
        let accentSecondaryColor;
        let textColor;
        let backgroundMutedColor;
        let baseDuration;
        let standardEase;

        function getCSSTokens() {
            const cs = getComputedStyle(document.documentElement);
            accentPrimaryColor = cs.getPropertyValue('--color-accent-primary').trim();
            accentSecondaryColor = cs.getPropertyValue('--color-accent-secondary').trim();
            textColor = cs.getPropertyValue('--color-text-primary').trim();
            backgroundMutedColor = cs.getPropertyValue('--color-background-muted').trim();
            baseDuration = parseFloat(cs.getPropertyValue('--duration-base'));
            standardEase = cs.getPropertyValue('--ease-standard').trim();

            // Update initial animation duration based on token if slider value matches default
            if (animationDuration === 0.22) { // Default slider value
                animationDuration = baseDuration;
                speedSlider.value = baseDuration; // Sync slider value if it was default
            }
        }

        // --- Array Generation and Rendering ---
        function generateRandomArray() {
            arr = Array.from({ length: ARRAY_SIZE }, () =>
                Math.floor(Math.random() * (INITIAL_MAX_VALUE - INITIAL_MIN_VALUE + 1)) + INITIAL_MIN_VALUE
            );
        }

        function renderBars(animate = false) {
            svg.innerHTML = ''; // Clear existing bars

            const maxVal = Math.max(...arr);
            const barWidth = SVG_WIDTH / (ARRAY_SIZE * (1 + BAR_SPACING_RATIO));
            const barSpacing = barWidth * BAR_SPACING_RATIO;
            const availableWidth = SVG_WIDTH - (ARRAY_SIZE - 1) * barSpacing;
            const actualBarWidth = availableWidth / ARRAY_SIZE;

            arr.forEach((value, index) => {
                const barHeight = (value / maxVal) * (SVG_HEIGHT * 0.8); // Scale height to 80% of SVG height
                const x = index * (actualBarWidth + barSpacing);
                const y = SVG_HEIGHT - barHeight; // Bars grow upwards from the bottom

                // Create rectangle
                const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                rect.setAttribute('x', x);
                rect.setAttribute('y', animate ? SVG_HEIGHT : y); // Start from bottom if animating
                rect.setAttribute('width', actualBarWidth);
                rect.setAttribute('height', animate ? 0 : barHeight); // Start from 0 height if animating
                rect.classList.add('bar-rect');
                rect.dataset.index = index;
                svg.appendChild(rect);

                // Create text label
                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', x + actualBarWidth / 2);
                text.setAttribute('y', animate ? SVG_HEIGHT - 10 : y - 10); // Position above bar
                text.classList.add('bar-label');
