        // --- Bubble Sort Logic ---
        function bubbleSortStep() {
            if (isSortingComplete) {
                updateObservation("排序已完成！");
                nextStepButton.disabled = true;
                return;
            }

            const bars = Array.from(svg.querySelectorAll('.bar-rect'));
            const labels = Array.from(svg.querySelectorAll('.bar-label'));

            // Remove all previous highlights
            bars.forEach(bar => bar.classList.remove('comparing'));
            labels.forEach(label => label.style.fill = textColor);

            let action = "";
            let swapped = false;

            if (j < ARRAY_SIZE - 1 - i) {
                // Highlight current comparison elements
                const bar1 = bars[j];
                const bar2 = bars[j + 1];
                const label1 = labels[j];
                const label2 = labels[j + 1];

                bar1.classList.add('comparing');
                bar2.classList.add('comparing');
                label1.style.fill = accentPrimaryColor;
                label2.style.fill = accentPrimaryColor;

                gsap.timeline({
                    onComplete: () => {
                        // After highlight, perform comparison and potential swap
                        if (arr[j] > arr[j + 1]) {
                            // Swap elements in array
                            [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                            swapped = true;
                            action = "元素已交换";

                            // Animate swap
                            const x1 = parseFloat(bar1.getAttribute('x'));
                            const x2 = parseFloat(bar2.getAttribute('x'));

                            gsap.to(bar1, { x: x2, duration: animationDuration, ease: standardEase });
                            gsap.to(bar2, { x: x1, duration: animationDuration, ease: standardEase });
                            gsap.to(label1, { x: x2 + parseFloat(bar1.getAttribute('width')) / 2, duration: animationDuration, ease: standardEase });
                            gsap.to(label2, { x: x1 + parseFloat(bar2.getAttribute('width')) / 2, duration: animationDuration, ease: standardEase });

                            // Update data-index for correct re-selection in next step
                            bar1.dataset.index = j + 1;
                            bar2.dataset.index = j;
                            label1.dataset.index = j + 1;
                            label2.dataset.index = j;

                            // Reorder DOM elements to match new visual order
                            // This is important for subsequent selections by index
                            const parent = bar1.parentNode;
                            if (parent) {
                                if (j < j + 1) { // Normal swap
                                    parent.insertBefore(bar2, bar1);
                                    parent.insertBefore(label2, label1);
                                } else { // Should not happen with j and j+1
                                    parent.insertBefore(bar1, bar2);
                                    parent.insertBefore(label1, label2);
                                }
                            }

                            // Re-sort the bars and labels arrays based on their new data-index
                            bars.sort((a, b) => parseInt(a.dataset.index) - parseInt(b.dataset.index));
                            labels.sort((a, b) => parseInt(a.dataset.index) - parseInt(b.dataset.index));

                        } else {
                            action = "无需交换";
                        }

                        // After animation, remove comparison highlight
                        gsap.to([bar1, bar2], {
                            fill: backgroundMutedColor,
                            duration: animationDuration / 2,
                            ease: standardEase,
                            delay: animationDuration / 2, // Wait for swap animation to finish
                            onComplete: () => {
                                bar1.classList.remove('comparing');
                                bar2.classList.remove('comparing');
                                label1.style.fill = textColor;
                                label2.style.fill = textColor;
                            }
                        });

                        updateObservation(`比较索引 ${j} 和 ${j + 1} 的元素。${action}。`);
                        j++;
                        window.PrimoriaInteractive.track('control_changed', { control: 'next_step', index1: j - 1, index2: j, action: action, swapped: swapped });
                    }
                });

            } else {
                // End of a pass
                sortedCount++;
                i++;
                j = 0; // Reset j for the next pass

                // Mark the last 'i' elements as sorted
                const sortedBar = bars[ARRAY_SIZE - i];
                const sortedLabel = labels[ARRAY_SIZE - i];
                gsap.to(sortedBar, { fill: accentSecondaryColor, duration: animationDuration, ease: standardEase });
                gsap.to(sortedLabel, { fill: textColor, duration: animationDuration, ease: standardEase });

                if (i >= ARRAY_SIZE - 1) {
                    isSortingComplete = true;
                    // Mark all bars as sorted
                    bars.forEach(bar => gsap.to(bar, { fill: accentSecondaryColor, duration: animationDuration, ease: standardEase }));
                    labels.forEach(label => gsap.to(label, { fill: textColor, duration: animationDuration, ease: standardEase }));
                    updateObservation("排序已完成！");
                    nextStepButton.disabled = true;
                } else {
                    updateObservation(`第 ${i} 轮完成。已排序元素：${sortedCount}。`);
                }
            }
        }

        // --- Observation Update ---
        function updateObservation(message) {
            observationText.textContent = message;
        }

        // --- Event Handlers ---
        nextStepButton.addEventListener('click', () => {
            bubbleSortStep();
        });

        resetButton.addEventListener('click', () => {
            resetAlgorithm();
            window.PrimoriaInteractive.track('reset_pressed');
        });

        speedSlider.addEventListener('input', () => {
            animationDuration = parseFloat(speedSlider.value);
            let speedLabel = "慢";
            if (animationDuration <= baseDuration * 0.75) speedLabel = "快";
            else if (animationDuration <= baseDuration * 1.25) speedLabel = "中";
            else speedLabel = "慢";
            animationSpeedValue.textContent = speedLabel;
            window.PrimoriaInteractive.track('control_changed', { control: 'animation_speed', value: animationDuration, label: speedLabel });
        });

        // --- Initial Setup ---
        function resetAlgorithm() {
            generateRandomArray();
            i = 0;
            j = 0;
            sortedCount = 0;
            isSortingComplete = false;
            renderBars(true); // Animate initial bar drawing
            updateObservation("点击“下一步”开始冒泡排序。");
            nextStepButton.disabled = false;
        }

        // Initialize on load
        document.addEventListener('DOMContentLoaded', () => {
            getCSSTokens();
            resetAlgorithm();
        });
    </script>
