<body>
    <div class="iv-shell">
        <header class="iv-header">
            <p class="iv-kicker">数据结构与算法</p>
            <h1 class="iv-title">冒泡排序可视化</h1>
            <p class="iv-subtitle">通过逐步比较和交换元素，观察冒泡排序如何将一组数字从小到大排列。</p>
        </header>

        <div class="iv-layout">
            <div class="iv-visual-card">
                <svg id="bubbleSortSVG" viewBox="0 0 600 300" preserveAspectRatio="xMidYMid meet" aria-label="冒泡排序可视化区域，柱状图表示数字，高亮显示正在比较的元素。"></svg>
            </div>

            <div class="iv-controls-card">
                <div class="iv-control-row">
                    <button id="nextStepButton" aria-label="执行冒泡排序的下一步操作">下一步</button>
                    <button id="resetButton" aria-label="重置排序，生成新的随机数组">重置</button>
                </div>
                <div class="iv-control">
                    <div class="iv-control-label-group">
                        <label for="animationSpeedSlider" class="iv-label">动画速度</label>
                        <span id="animationSpeedValue" class="iv-value">中</span>
                    </div>
                    <input type="range" id="animationSpeedSlider" min="0.1" max="1.0" step="0.05" value="0.22" aria-label="调整排序动画的播放速度">
                </div>
            </div>
        </div>

        <div class="iv-observation-card">
            <p id="observationText" class="iv-conclusion" aria-live="polite">点击“下一步”开始冒泡排序。</p>
        </div>
    </div>

    <script type="module">
        import gsap from "https://esm.sh/gsap";

        // --- Primoria Interactive Tracking Bridge ---
        // Ensure window.PrimoriaInteractive is available
        if (typeof window.PrimoriaInteractive === 'undefined') {
            window.PrimoriaInteractive = {
                track: (eventName, payload) => {
                    console.log(`[PrimoriaInteractive.track] Event: ${eventName}, Payload:`, payload);
                }
            };
        }

        // --- Configuration and DOM Elements ---
        const ARRAY_SIZE = 10;
        const INITIAL_MIN_VALUE = 10;
        const INITIAL_MAX_VALUE = 99;
        const SVG_WIDTH = 600;
        const SVG_HEIGHT = 300;
        const BAR_SPACING_RATIO = 0.1; // Ratio of spacing to bar width

        const svg = document.getElementById('bubbleSortSVG');
        const nextStepButton = document.getElementById('nextStepButton');
        const resetButton = document.getElementById('resetButton');
        const speedSlider = document.getElementById('animationSpeedSlider');
        const animationSpeedValue = document.getElementById('animationSpeedValue');
        const observationText = document.getElementById('observationText');

        let arr = [];
        let i = 0; // Outer loop index (passes)
        let j = 0; // Inner loop index (comparisons in current pass)
        let sortedCount = 0; // Number of elements confirmed in their final sorted position
        let isSortingComplete = false;
        let animationDuration = parseFloat(speedSlider.value); // Initial animation duration

        // --- CSS Token Values (read at runtime) ---
        let accentPrimaryColor;
        let accentSecondaryColor;
        let textColor;
        let backgroundMutedColor;
        let baseDuration;
        let standardEase;

        function getCSSTokens() {
            const cs = getComputedStyle(document.documentElement);
            accentPrimaryColor = cs.getPropertyValue('--color-accent-primary').trim();
            accentSecondaryColor = cs.getPropertyValue('--color-accent-secondary').trim();
            textColor = cs.getPropertyValue('--color-text-primary').trim();
            backgroundMutedColor = cs.getPropertyValue('--color-background-muted').trim();
            baseDuration = parseFloat(cs.getPropertyValue('--duration-base'));
            standardEase = cs.getPropertyValue('--ease-standard').trim();

            // Update initial animation duration based on token if slider value matches default
            if (animationDuration === 0.22) { // Default slider value
                animationDuration = baseDuration;
                speedSlider.value = baseDuration; // Sync slider value if it was default
            }
        }

        // --- Array Generation and Rendering ---
        function generateRandomArray() {
            arr = Array.from({ length: ARRAY_SIZE }, () =>
                Math.floor(Math.random() * (INITIAL_MAX_VALUE - INITIAL_MIN_VALUE + 1)) + INITIAL_MIN_VALUE
            );
        }

        function renderBars(animate = false) {
            svg.innerHTML = ''; // Clear existing bars

            const maxVal = Math.max(...arr);
            const barWidth = SVG_WIDTH / (ARRAY_SIZE * (1 + BAR_SPACING_RATIO));
            const barSpacing = barWidth * BAR_SPACING_RATIO;
            const availableWidth = SVG_WIDTH - (ARRAY_SIZE - 1) * barSpacing;
            const actualBarWidth = availableWidth / ARRAY_SIZE;

            arr.forEach((value, index) => {
                const barHeight = (value / maxVal) * (SVG_HEIGHT * 0.8); // Scale height to 80% of SVG height
                const x = index * (actualBarWidth + barSpacing);
                const y = SVG_HEIGHT - barHeight; // Bars grow upwards from the bottom

                // Create rectangle
                const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                rect.setAttribute('x', x);
                rect.setAttribute('y', animate ? SVG_HEIGHT : y); // Start from bottom if animating
                rect.setAttribute('width', actualBarWidth);
                rect.setAttribute('height', animate ? 0 : barHeight); // Start from 0 height if animating
                rect.classList.add('bar-rect');
                rect.dataset.index = index;
                svg.appendChild(rect);

                // Create text label
                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', x + actualBarWidth / 2);
                text.setAttribute('y', animate ? SVG_HEIGHT - 10 : y - 10); // Position above bar
                text.classList.add('bar-label');
                text.textContent = value;
                text.dataset.index = index;
                svg.appendChild(text);

                if (animate) {
                    gsap.to(rect, {
                        y: y,
                        height: barHeight,
                        duration: animationDuration,
                        ease: standardEase,
                        delay: index * 0.05 // Stagger animation
                    });
                    gsap.to(text, {
                        y: y - 10,
                        duration: animationDuration,
                        ease: standardEase,
                        delay: index * 0.05
                    });
                }
            });
        }

        // --- Bubble Sort Logic ---
        function bubbleSortStep() {
            if (isSortingComplete) {
                updateObservation("排序已完成！");
                nextStepButton.disabled = true;
                return;
            }

            const bars = Array.from(svg.querySelectorAll('.bar-rect'));
            const labels = Array.from(svg.querySelectorAll('.bar-label'));

            // Remove all previous highlights
            bars.forEach(bar => bar.classList.remove('comparing'));
            labels.forEach(label => label.style.fill = textColor);

            let action = "";
            let swapped = false;

            if (j < ARRAY_SIZE - 1 - i) {
                // Highlight current comparison elements
                const bar1 = bars[j];
                const bar2 = bars[j + 1];
                const label1 = labels[j];
                const label2 = labels[j + 1];

                bar1.classList.add('comparing');
                bar2.classList.add('comparing');
                label1.style.fill = accentPrimaryColor;
                label2.style.fill = accentPrimaryColor;

                gsap.timeline({
                    onComplete: () => {
                        // After highlight, perform comparison and potential swap
                        if (arr[j] > arr[j + 1]) {
                            // Swap elements in array
                            [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                            swapped = true;
                            action = "元素已交换";

                            // Animate swap
                            const x1 = parseFloat(bar1.getAttribute('x'));
                            const x2 = parseFloat(bar2.getAttribute('x'));

                            gsap.to(bar1, { x: x2, duration: animationDuration, ease: standardEase });
                            gsap.to(bar2, { x: x1, duration: animationDuration, ease: standardEase });
                            gsap.to(label1, { x: x2 + parseFloat(bar1.getAttribute('width')) / 2, duration: animationDuration, ease: standardEase });
                            gsap.to(label2, { x: x1 + parseFloat(bar2.getAttribute('width')) / 2, duration: animationDuration, ease: standardEase });

                            // Update data-index for correct re-selection in next step
                            bar1.dataset.index = j + 1;
                            bar2.dataset.index = j;
                            label1.dataset.index = j + 1;
                            label2.dataset.index = j;

                            // Reorder DOM elements to match new visual order
                            // This is important for subsequent selections by index
                            const parent = bar1.parentNode;
                            if (parent) {
                                if (j < j + 1) { // Normal swap
                                    parent.insertBefore(bar2, bar1);
                                    parent.insertBefore(label2, label1);
                                } else { // Should not happen with j and j+1
                                    parent.insertBefore(bar1, bar2);
                                    parent.insertBefore(label1, label2);
                                }
                            }

                            // Re-sort the bars and labels arrays based on their new data-index
                            bars.sort((a, b) => parseInt(a.dataset.index) - parseInt(b.dataset.index));
                            labels.sort((a, b) => parseInt(a.dataset.index) - parseInt(b.dataset.index));

                        } else {
                            action = "无需交换";
                        }

                        // After animation, remove comparison highlight
                        gsap.to([bar1, bar2], {
                            fill: backgroundMutedColor,
                            duration: animationDuration / 2,
                            ease: standardEase,
                            delay: animationDuration / 2, // Wait for swap animation to finish
                            onComplete: () => {
                                bar1.classList.remove('comparing');
                                bar2.classList.remove('comparing');
                                label1.style.fill = textColor;
                                label2.style.fill = textColor;
                            }
                        });

                        updateObservation(`比较索引 ${j} 和 ${j + 1} 的元素。${action}。`);
                        j++;
                        window.PrimoriaInteractive.track('control_changed', { control: 'next_step', index1: j - 1, index2: j, action: action, swapped: swapped });
                    }
                });

            } else {
                // End of a pass
                sortedCount++;
                i++;
                j = 0; // Reset j for the next pass

                // Mark the last 'i' elements as sorted
                const sortedBar = bars[ARRAY_SIZE - i];
                const sortedLabel = labels[ARRAY_SIZE - i];
                gsap.to(sortedBar, { fill: accentSecondaryColor, duration: animationDuration, ease: standardEase });
                gsap.to(sortedLabel, { fill: textColor, duration: animationDuration, ease: standardEase });

                if (i >= ARRAY_SIZE - 1) {
                    isSortingComplete = true;
                    // Mark all bars as sorted
                    bars.forEach(bar => gsap.to(bar, { fill: accentSecondaryColor, duration: animationDuration, ease: standardEase }));
                    labels.forEach(label => gsap.to(label, { fill: textColor, duration: animationDuration, ease: standardEase }));
                    updateObservation("排序已完成！");
                    nextStepButton.disabled = true;
                } else {
                    updateObservation(`第 ${i} 轮完成。已排序元素：${sortedCount}。`);
                }
            }
        }

        // --- Observation Update ---
        function updateObservation(message) {
            observationText.textContent = message;
        }

        // --- Event Handlers ---
        nextStepButton.addEventListener('click', () => {
            bubbleSortStep();
        });

        resetButton.addEventListener('click', () => {
            resetAlgorithm();
            window.PrimoriaInteractive.track('reset_pressed');
        });

        speedSlider.addEventListener('input', () => {
            animationDuration = parseFloat(speedSlider.value);
            let speedLabel = "慢";
            if (animationDuration <= baseDuration * 0.75) speedLabel = "快";
            else if (animationDuration <= baseDuration * 1.25) speedLabel = "中";
            else speedLabel = "慢";
            animationSpeedValue.textContent = speedLabel;
            window.PrimoriaInteractive.track('control_changed', { control: 'animation_speed', value: animationDuration, label: speedLabel });
        });

        // --- Initial Setup ---
        function resetAlgorithm() {
            generateRandomArray();
            i = 0;
            j = 0;
            sortedCount = 0;
            isSortingComplete = false;
            renderBars(true); // Animate initial bar drawing
            updateObservation("点击“下一步”开始冒泡排序。");
            nextStepButton.disabled = false;
        }

        // Initialize on load
        document.addEventListener('DOMContentLoaded', () => {
            getCSSTokens();
            resetAlgorithm();
        });
    </script>
