        /** Renders or updates the SVG bars. */
        function renderBars(data, highlightJ = -1, highlightJ1 = -1, swappedIdx = -1) {
            updateScales(); // Recalculate scales on render to handle resize

            const bars = svg.selectAll(".bubble-sort-bar")
                .data(data, (d, idx) => idx); // Use index as key for data binding

            // Exit old elements (not strictly needed for fixed NUM_BARS, but good practice)
            bars.exit().remove();

            // Enter new elements
            const enteringBars = bars.enter().append("rect")
                .attr("class", "bubble-sort-bar")
                .attr("x", (d, idx) => xScale(idx))
                .attr("y", (d) => visualCard.clientHeight - yScale(d))
                .attr("width", xScale.bandwidth())
                .attr("height", (d) => yScale(d))
                .attr("aria-label", (d, idx) => `值: ${d}, 位置: ${idx + 1}`);

