        const directPattern = /parseFloat\s*\([^)]*--duration-[^)]*\)\s*(?!\s*\/\s*1000)/;
        if (directPattern.test(stripped)) {
          // Now confirm the result is actually used as a gsap duration. Cheap proxy: file contains gsap.* and duration:
          if (/gsap\s*\./.test(stripped) && /duration\s*:/.test(stripped)) {
