            return `document.getElementById("${m[1]}") targets an id not present in the HTML.`;
          }
        }
        while ((m = queryHashRe.exec(script.body))) {
          if (!ids.has(m[1])) {
            return `document.querySelector("#${m[1]}") targets an id not present in the HTML.`;
          }
        }
      }
      return null;
    },
  },
