    key: 'gsap-css-bezier-ease',
    severity: 'blocker',
    hint: 'gsap.to ease must be a named ease ("power2.out", "sine.inOut", etc.) or a function. CSS cubic-bezier(...) strings silently fall back to linear.',
    check: ({ scripts }) => {
