  if (!result.success) {
    throw new AuditParseError(
      'Audit JSON did not match the required schema.',
      result.error.issues.map((i) => `${i.path.join('.') || '(root)'}: ${i.message}`),
      raw,
    );
  }
  return result.data;
}

