32	const ENGINE_OPTIONS = [
33	  { value: 'physics-canvas', label: 'Physics canvas' },
34	  { value: 'html-iframe', label: 'HTML iframe' },
35	  { value: 'r3f-cell-3d', label: '3D cell renderer' },
36	] as const;
