38	const schema = z.object({
39	  engine: z.enum(['physics-canvas', 'html-iframe', 'r3f-cell-3d']),
40	  template: z.string(),
41	  title: z.string().optional(),
42	  description: z.string().optional(),
43	  aiPrompt: z.string().optional(),
44	  amplitude: z.coerce.number().min(0.2).max(2.5),
45	  frequency: z.coerce.number().min(0.5).max(4),
46	  phase: z.coerce.number().min(0).max(6.3),
47	  speed: z.coerce.number().min(0).max(2),
48	});
