50	type FormValues = z.infer<typeof schema>;
51	
52	function resolveEditorEngine(engine: string | undefined): FormValues['engine'] {
53	  if (engine === 'r3f-cell-3d' || engine === 'physics-canvas') {
54	    return engine;
55	  }
56	  if (engine === 'html-iframe' || engine === 'interactive-html5' || engine === 'gemini-html5' || engine === 'fallback-html5') {
57	    return 'html-iframe';
58	  }
59	  return 'html-iframe';
60	}
61	
62	function containsChineseText(value: string) {
63	  return /[\u3400-\u9fff\uf900-\ufaff]/.test(value);
64	}
65	
66	function resolveGenerationLanguage(prompt: string, productLanguage: 'en' | 'zh-CN') {
67	  return containsChineseText(prompt) ? 'zh-CN' : productLanguage;
68	}
69	
70	interface InteractiveVisualPanelProps {
71	  block: Block;
72	  lessonId: string;
73	  pageId: string;
74	}
75	
76	export function InteractiveVisualPanel({ block, lessonId, pageId }: InteractiveVisualPanelProps) {
77	  const dispatch = useAppDispatch();
78	  const language = useProductLanguage();
79	  const [genError, setGenError] = useState<string | null>(null);
80	  const [isGenerating, setIsGenerating] = useState(false);
81	  const [generationJob, setGenerationJob] = useState<InteractiveVisualGenerationJob | null>(null);
82	  const c = block.content as {
83	    engine?: string;
84	    template?: string;
85	    title?: string;
86	    description?: string;
87	    aiPrompt?: string;
88	    runtime?: {
89	      simulation?: string;
90	      params?: {
91	        amplitude?: number;
92	        frequency?: number;
93	        phase?: number;
94	        speed?: number;
95	      };
96	    };
97	  };
98	  const waveParams = c.runtime?.simulation === 'wave' ? c.runtime.params : undefined;
99	  const resolvedEngine = resolveEditorEngine(c.engine);
100	  const formValues: FormValues = {
101	    engine: resolvedEngine,
102	    template: c.template ?? (resolvedEngine === 'physics-canvas' ? 'wave' : 'generic'),
103	    title: c.title ?? '',
104	    description: c.description ?? '',
105	    aiPrompt: c.aiPrompt ?? '',
106	    amplitude: waveParams?.amplitude ?? 1,
107	    frequency: waveParams?.frequency ?? 1,
108	    phase: waveParams?.phase ?? 0,
109	    speed: waveParams?.speed ?? 0.7,
110	  };
111	
112	  const { control, register, watch, reset, getValues } = useForm<FormValues>({
113	    resolver: zodResolver(schema),
114	    defaultValues: formValues,
115	  });
116	  const [selectedEngine, amplitude, frequency, phase, speed] = useWatch({
117	    control,
118	    name: ['engine', 'amplitude', 'frequency', 'phase', 'speed'],
119	  });
120	
121	  useSyncedInspectorForm({
122	    entityKey: block.id,
123	    sourceValues: formValues,
124	    reset,
125	    watch,
126	    onChange: (values) => {
127	      const nextContent: Record<string, unknown> = {
128	        ...(block.content as object),
129	        engine: values.engine,
130	        template: values.engine === 'physics-canvas' ? 'wave' : values.template,
131	        title: values.title,
132	        description: values.description,
133	        aiPrompt: values.aiPrompt,
134	      };
135	
136	      if (values.engine === 'physics-canvas') {
137	        nextContent.runtime = {
138	          simulation: 'wave',
139	          params: {
140	            amplitude: values.amplitude,
141	            frequency: values.frequency,
142	            phase: values.phase,
143	            speed: values.speed,
144	          },
145	        };
146	      } else {
147	        delete nextContent.runtime;
148	      }
149	
150	      dispatch(
151	        updateBlock({
152	          lessonId,
153	          pageId,
154	          block: { ...block, content: nextContent },
155	        }),
156	      );
157	    },
158	  });
159	
160	  async function handleGenerate() {
161	    const values = getValues();
162	    const prompt = values.aiPrompt?.trim() ?? '';
163	    if (prompt.length < 8) {
164	      setGenError('Describe the interactive visual in at least a few words before generating.');
165	      return;
166	    }
167	
168	    setIsGenerating(true);
169	    setGenError(null);
170	    setGenerationJob(null);
171	
172	    try {
173	      const artifact = await createInteractiveVisual({
174	        prompt,
175	        template: values.template,
176	        title: values.title?.trim() || undefined,
177	        description: values.description?.trim() || undefined,
178	        language: resolveGenerationLanguage(prompt, language),
179	        surface: 'builder',
180	        allowFallback: false,
181	        onJobUpdate: setGenerationJob,
182	      });
183	      const currentContent = block.content && typeof block.content === 'object' ? (block.content as Record<string, unknown>) : {};
184	      const baseContent = { ...currentContent };
185	      delete baseContent.runtime;
186	      const nextContent: Record<string, unknown> = {
187	        ...baseContent,
188	        version: artifact.version,
